// Compile-time contract between the Go DTOs (generated by Wails into wailsjs/go/models.ts)
// and the hand-written TypeScript mirrors in this folder. It produces no runtime code:
// `npm run typecheck` fails when a field is added, renamed or removed on one side only.
import type { backup, database, datasets, domain, engine, genetics, service } from '../../wailsjs/go/models'
import type { AppInfo, DbHealth } from './app'
import type * as D from './domain'
import type * as E from './engine'

type Keys<T> = Exclude<keyof T, 'convertValues' | 'createFrom'>

/** `true` when both types have exactly the same property names; otherwise an object naming the differences. */
type SameKeys<Go, Ts> = [Keys<Go>] extends [Keys<Ts>]
  ? [Keys<Ts>] extends [Keys<Go>]
    ? true
    : { extraInTypeScript: Exclude<Keys<Ts>, Keys<Go>> }
  : { missingInTypeScript: Exclude<Keys<Go>, Keys<Ts>> }

/** `true` when every TypeScript property exists in Go (the TS type is an intentional subset). */
type SubsetOfGo<Go, Ts> = [Keys<Ts>] extends [Keys<Go>] ? true : { extraInTypeScript: Exclude<Keys<Ts>, Keys<Go>> }

type Assert<T extends true> = T

// ---- app / health
export type _AppInfo = Assert<SameKeys<service.AppInfo, AppInfo>>
export type _Health = Assert<SameKeys<database.Health, DbHealth>>

